import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"Filesystems","description":"","frontmatter":{},"headers":[],"relativePath":"manual/filesystems.md","filePath":"manual/filesystems.md"}'),o={name:"manual/filesystems.md"};function d(i,e,c,l,p,r){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="filesystems" tabindex="-1">Filesystems <a class="header-anchor" href="#filesystems" aria-label="Permalink to &quot;Filesystems&quot;">​</a></h1><h2 id="the-vfs-layer" tabindex="-1">The VFS layer <a class="header-anchor" href="#the-vfs-layer" aria-label="Permalink to &quot;The VFS layer&quot;">​</a></h2><p>The kernel VFS fronts four filesystem implementations:</p><table tabindex="0"><thead><tr><th>Type</th><th>Read</th><th>Write</th><th>Where it shines</th></tr></thead><tbody><tr><td>ramfs</td><td>yes</td><td>yes</td><td>the ISO root - everything in RAM</td></tr><tr><td>FAT32</td><td>yes</td><td>yes</td><td>interchange with every OS</td></tr><tr><td>exFAT</td><td>yes</td><td>yes</td><td>large removable volumes</td></tr><tr><td>ext4</td><td>read*</td><td>no*</td><td>inspecting Linux disks</td></tr></tbody></table><p>(*) the ext4 leg is mount/read-oriented in this release.</p><h2 id="day-to-day-file-work" tabindex="-1">Day-to-day file work <a class="header-anchor" href="#day-to-day-file-work" aria-label="Permalink to &quot;Day-to-day file work&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; files                  the wizard: ls / tree / df+du / cp / mv /</span></span>
<span class="line"><span>                            rm (confirmed) / edit / stat+chmod</span></span>
<span class="line"><span>ush&gt; files edit /etc/opencube.conf</span></span></code></pre></div><p>or the classic programs directly - <code>ls</code>, <code>tree</code>, <code>df</code>, <code>du</code>, <code>cp</code>, <code>mv</code>, <code>rm</code>, <code>edit</code>, <code>stat</code>, <code>chmod</code>, <code>cat</code>, <code>mkdir</code>, <code>ln</code>, <code>wc</code>, <code>grep</code>, <code>head</code>, <code>tail</code>, <code>sort</code>, <code>awk</code>. They are ordinary registry programs; <code>files</code> is a second door into the same binaries.</p><h2 id="formatting-and-mounting" tabindex="-1">Formatting and mounting <a class="header-anchor" href="#formatting-and-mounting" aria-label="Permalink to &quot;Formatting and mounting&quot;">​</a></h2><p><code>disk-tool</code> walks the whole flow:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool              -&gt; list devices (lsblk)</span></span>
<span class="line"><span>                           -&gt; partition table (parted)</span></span>
<span class="line"><span>                           -&gt; create a filesystem (mkfs.fat32 / exfat /</span></span>
<span class="line"><span>                              ext4 - the device name is asked, retyped</span></span>
<span class="line"><span>                              and confirmed)</span></span>
<span class="line"><span>                           -&gt; mount manager (list / mount / umount /</span></span>
<span class="line"><span>                              fatmount / fatstat)</span></span></code></pre></div><p>Classic form:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; mkfs.fat32 hd0p1       (destroys data - no wizard, no extra prompt)</span></span>
<span class="line"><span>ush&gt; mount fat32 hd0p1 /mnt</span></span>
<span class="line"><span>ush&gt; umount /mnt</span></span></code></pre></div><p><code>fatmount</code> is the FAT-specific convenience (auto-detects the FAT volume), <code>fatstat</code> reports FAT statistics, <code>fsck</code> checks a filesystem.</p><h2 id="the-etc-volume" tabindex="-1">The /etc volume <a class="header-anchor" href="#the-etc-volume" aria-label="Permalink to &quot;The /etc volume&quot;">​</a></h2><p><code>/etc/opencube.conf</code> carries the persistent configuration (update URLs, auto-check, online-update, shell language). On an ISO boot it lives in RAM and resets on reboot; on an installed system (or when an <code>etc.img</code> disk is attached) it persists:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; config list</span></span>
<span class="line"><span>ush&gt; config get update_url</span></span>
<span class="line"><span>ush&gt; config set online_update no</span></span>
<span class="line"><span>ush&gt; config restore         (back to defaults)</span></span></code></pre></div><h2 id="paths-and-the-current-directory" tabindex="-1">Paths and the current directory <a class="header-anchor" href="#paths-and-the-current-directory" aria-label="Permalink to &quot;Paths and the current directory&quot;">​</a></h2><p><code>cd</code>, <code>pwd</code>, <code>ls</code> behave like their Unix namesakes; paths are <code>/</code> separated, absolute from the ramfs root. The editor writes back in place; <code>cp</code>/<code>mv</code>/<code>rm</code>/<code>chmod</code>/<code>stat</code> take the obvious shapes (<code>chmod &lt;octal&gt; &lt;path&gt;</code>).</p><h2 id="what-is-where-on-a-running-system" tabindex="-1">What is where on a running system <a class="header-anchor" href="#what-is-where-on-a-running-system" aria-label="Permalink to &quot;What is where on a running system&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/            ramfs root (the ISO content)</span></span>
<span class="line"><span>/etc         the config volume (persisted when etc.img is attached)</span></span>
<span class="line"><span>/mnt, /media conventional mount points</span></span>
<span class="line"><span>/bin, /lib   the embedded program registry is in-kernel; these</span></span>
<span class="line"><span>             paths exist for the dynamic-linker leg (ld.so, libfoo)</span></span></code></pre></div>`,21)])])}const u=a(o,[["render",d]]);export{m as __pageData,u as default};
